rules.logic:
// Idempotency guard
if (element.querySelector('.pwe-pin-action-bar')) return;

// Get the pin URL from the anchor tag inside the card
const anchor = element.querySelector('a[href*="/pin/"]');
const pinUrl = anchor ? 'https://www.pinterest.com' + anchor.getAttribute('href').replace('https://www.pinterest.com', '') : '';

// Get the image src for download
const img = element.querySelector('img');
const imgSrc = img ? img.src : '';

// Get the alt text for a filename hint
const altText = anchor ? (anchor.getAttribute('aria-label') || 'pinterest-pin') : 'pinterest-pin';
const safeFilename = altText.replace(/[^a-z0-9]/gi, '-').toLowerCase().slice(0, 40) + '.jpg';

// Create action bar container
const bar = document.createElement('div');
bar.className = 'pwe-pin-action-bar';
bar.style.cssText = `
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 7px 10px 6px;
  background: #fff;
  border-top: 1px solid #efefef;
  border-radius: 0 0 16px 16px;
  width: 100%;
  box-sizing: border-box;
  position: relative;
  z-index: 2;
`;

// ---- Share Button ----
const shareBtn = document.createElement('button');
shareBtn.title = 'Share this Pin';
shareBtn.style.cssText = `
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  justify-content: center;
  padding: 6px 10px;
  background: #f0f0f0;
  color: #333;
  border: none;
  border-radius: 20px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  font-family: inherit;
  transition: background 0.15s;
  white-space: nowrap;
`;
shareBtn.innerHTML = `
  <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
    <circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/>
    <line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/>
  </svg>
  <span>Share</span>
`;
shareBtn.addEventListener('mouseover', () => { shareBtn.style.background = '#e0e0e0'; });
shareBtn.addEventListener('mouseout',  () => { shareBtn.style.background = '#f0f0f0'; });
shareBtn.addEventListener('click', (e) => {
  e.preventDefault();
  e.stopPropagation();
  const fullUrl = pinUrl.startsWith('http') ? pinUrl : 'https://www.pinterest.com' + pinUrl;
  if (navigator.share) {
    navigator.share({ title: altText, url: fullUrl }).catch(() => {});
  } else {
    navigator.clipboard.writeText(fullUrl).then(() => {
      const span = shareBtn.querySelector('span');
      const orig = span.textContent;
      span.textContent = 'Copied!';
      shareBtn.style.background = '#e1f5e1';
      setTimeout(() => { span.textContent = orig; shareBtn.style.background = '#f0f0f0'; }, 1800);
    }).catch(() => { window.open('https://pinterest.com/pin/create/button/?url=' + encodeURIComponent(fullUrl), '_blank'); });
  }
});

// ---- Download Button ----
const dlBtn = document.createElement('button');
dlBtn.title = 'Download this Pin';
dlBtn.style.cssText = `
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  justify-content: center;
  padding: 6px 10px;
  background: #e60023;
  color: #fff;
  border: none;
  border-radius: 20px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  font-family: inherit;
  transition: background 0.15s;
  white-space: nowrap;
`;
dlBtn.innerHTML = `
  <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
    <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
    <polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/>
  </svg>
  <span>Download</span>
`;
dlBtn.addEventListener('mouseover', () => { dlBtn.style.background = '#ad081b'; });
dlBtn.addEventListener('mouseout',  () => { dlBtn.style.background = '#e60023'; });
dlBtn.addEventListener('click', (e) => {
  e.preventDefault();
  e.stopPropagation();
  if (imgSrc) {
    const a = document.createElement('a');
    a.href = imgSrc;
    a.download = safeFilename;
    a.target = '_blank';
    a.rel = 'noopener noreferrer';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    const span = dlBtn.querySelector('span');
    const orig = span.textContent;
    span.textContent = 'Saving…';
    dlBtn.style.background = '#333';
    setTimeout(() => { span.textContent = orig; dlBtn.style.background = '#e60023'; }, 1800);
  }
});

bar.appendChild(shareBtn);
bar.appendChild(dlBtn);

// Insert the bar at the bottom of the pin card
element.style.position = 'relative';
element.style.display = 'flex';
element.style.flexDirection = 'column';
element.appendChild(bar);
